1	-- Scanner: entrada/saída por bip não pode mais travar por "lote morto".
2	--
3	-- Contexto: o QR congela o id do lote no momento da impressão. Como `lotes`
4	-- é duplicado por código (mesma data vira vários ids) e os duplicados são
5	-- deletados depois, a FK `etiquetas_qr.lote_id` (ON DELETE SET NULL) zera o
6	-- vínculo da linha — mas o QR continua apontando o id antigo. Ao dar entrada,
7	-- o Scanner gravava esse id morto em `movimentacoes.lote_id` (FK NO ACTION) e
8	-- o banco rejeitava (`movimentacoes_lote_id_fkey`), travando a caixa.
9	--
10	-- Solução: resolver SEMPRE um lote VIVO pela própria etiqueta — prioriza o
11	-- lote_id da linha; se morto/ausente, re-vincula por código + validade (o
12	-- mesmo lote existe sob outro id); se ainda assim não houver, grava NULL
13	-- (a entrada acontece e o código do lote fica na observação).
14	
15	-- ── Helper reutilizável: lote vivo a partir do UID da etiqueta ───────────────
16	CREATE OR REPLACE FUNCTION public.resolver_lote_etiqueta(p_uid text)
17	RETURNS uuid
18	LANGUAGE plpgsql
19	SECURITY DEFINER
20	SET search_path TO 'public'
21	AS $fn$
22	DECLARE
23	    v_row_lote uuid;
24	    v_codigo   text;
25	    v_validade date;
26	    v_pid      integer;
27	    v_result   uuid;
28	BEGIN
29	    SELECT lote_id, lote_codigo_snapshot, lote_validade_snapshot, produto_master_id
30	      INTO v_row_lote, v_codigo, v_validade, v_pid
31	      FROM public.etiquetas_qr
32	     WHERE uid = p_uid;
33	
34	    -- 1) lote da linha, se ainda existe (caminho feliz)
35	    IF v_row_lote IS NOT NULL
36	       AND EXISTS (SELECT 1 FROM public.lotes WHERE id = v_row_lote) THEN
37	        RETURN v_row_lote;
38	    END IF;
39	
40	    -- 2) re-vincular por código + validade (+ produto) — desempata pelo mais recente
41	    IF v_codigo IS NOT NULL THEN
42	        SELECT id INTO v_result
43	          FROM public.lotes
44	         WHERE codigo = v_codigo
45	           AND (v_pid IS NULL OR produto_id = v_pid)
46	           AND (v_validade IS NULL OR data_validade = v_validade)
47	         ORDER BY created_at DESC
48	         LIMIT 1;
49	        IF v_result IS NOT NULL THEN
50	            RETURN v_result;
51	        END IF;
52	
53	        -- fallback: só por código + produto (ignora validade)
54	        SELECT id INTO v_result
55	          FROM public.lotes
56	         WHERE codigo = v_codigo
57	           AND (v_pid IS NULL OR produto_id = v_pid)
58	         ORDER BY created_at DESC
59	         LIMIT 1;
60	        IF v_result IS NOT NULL THEN
61	            RETURN v_result;
62	        END IF;
63	    END IF;
64	
65	    -- 3) nada encontrado → NULL (entrada grava sem vínculo de lote)
66	    RETURN NULL;
67	END;
68	$fn$;
69	
70	GRANT EXECUTE ON FUNCTION public.resolver_lote_etiqueta(text) TO authenticated, anon, service_role;
71	
72	-- ── RPC do Scanner: resolve lote vivo + marca duplicado ──────────────────────
73	CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(p_loja_id integer, p_tipo text, p_itens jsonb)
74	 RETURNS jsonb
75	 LANGUAGE plpgsql
76	 SECURITY DEFINER
77	 SET search_path TO 'public'
78	AS $function$
79	DECLARE
80	    v_usuario_id integer;
81	    v_item jsonb;
82	    v_id text;
83	    v_pid integer;
84	    v_uid text;
85	    v_lote_id uuid;
86	    v_qty numeric;
87	    v_disp numeric;
88	    v_interna numeric;
89	    v_tipo_embalagem text;
90	    v_embalagem_nome text;
91	    v_lote text;
92	    v_payload jsonb;
93	    v_bip jsonb;
94	    v_saldo_anterior numeric;
95	    v_saldo_novo numeric;
96	    v_motivo text;
97	    v_observacoes text;
98	    v_resultados jsonb := '[]'::jsonb;
99	    v_ok integer := 0;
100	    v_err integer := 0;
101	BEGIN
102	    BEGIN
103	        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
104	    EXCEPTION WHEN OTHERS THEN
105	        v_usuario_id := NULL;
106	    END;
107	
108	    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
109	    LOOP
110	        v_id := v_item->>'id';
111	        BEGIN
112	            v_pid := (v_item->>'pid')::integer;
113	            v_uid := NULLIF(v_item->>'uid', '');
114	            -- lote do payload é só dica; lid malformado não pode derrubar o item
115	            BEGIN
116	                v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
117	            EXCEPTION WHEN OTHERS THEN
118	                v_lote_id := NULL;
119	            END;
120	            v_qty := (v_item->>'qty')::numeric;
121	            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
122	            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
123	            v_lote := NULLIF(v_item->>'lote', '');
124	            v_payload := v_item->'payload';
125	
126	            IF v_uid IS NOT NULL THEN
127	                BEGIN
128	                    v_bip := public.bipar_etiqueta(
129	                        v_uid,
130	                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
131	                        jsonb_build_object(
132	                            'loja_id', p_loja_id,
133	                            'referencia_tipo', 'scanner_lote',
134	                            'payload', v_payload
135	                        )
136	                    );
137	                EXCEPTION WHEN OTHERS THEN
138	                    v_bip := NULL;
139	                END;
140	
141	                -- IDEMPOTENCIA: etiqueta ja contada nesta etapa (bip duplicado) → nao lanca de novo.
142	                IF v_bip IS NOT NULL AND COALESCE((v_bip->>'ok')::boolean, true) = false THEN
143	                    v_resultados := v_resultados || jsonb_build_object(
144	                        'id', v_id, 'ok', false, 'duplicado', true,
145	                        'erro', COALESCE(NULLIF(v_bip->>'erro',''),
146	                                         CASE WHEN p_tipo = 'entrada'
147	                                              THEN 'Esta caixa já teve entrada registrada'
148	                                              ELSE 'Esta caixa já teve saída registrada' END)
149	                    );
150	                    v_err := v_err + 1;
151	                    CONTINUE;
152	                END IF;
153	
154	                -- QTY AUTORITATIVA: o que a caixa realmente tem.
155	                SELECT quantidade_disponivel, quantidade_interna
156	                  INTO v_disp, v_interna
157	                  FROM etiquetas_qr
158	                 WHERE uid = v_uid;
159	                v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0), v_qty);
160	            END IF;
161	
162	            IF v_qty IS NULL OR v_qty <= 0 THEN
163	                RAISE EXCEPTION '%', CASE WHEN p_tipo='entrada'
164	                    THEN 'Sem quantidade para dar entrada'
165	                    ELSE 'Container ja vazio — nada para dar saida' END;
166	            END IF;
167	
168	            SELECT COALESCE(quantidade_atual, 0)
169	              INTO v_saldo_anterior
170	              FROM estoque
171	             WHERE produto_master_id = v_pid
172	               AND loja_id = p_loja_id;
173	
174	            v_saldo_anterior := COALESCE(v_saldo_anterior, 0);
175	
176	            IF p_tipo = 'entrada' THEN
177	                v_saldo_novo := v_saldo_anterior + v_qty;
178	            ELSE
179	                v_saldo_novo := GREATEST(0, v_saldo_anterior - v_qty);
180	            END IF;
181	
182	            -- LOTE VIVO: prioriza a linha da etiqueta; re-vincula por código/validade;
183	            -- senão NULL. Nunca grava id de lote inexistente (evita FK e não trava).
184	            IF v_uid IS NOT NULL THEN
185	                v_lote_id := public.resolver_lote_etiqueta(v_uid);
186	            END IF;
187	            IF v_lote_id IS NOT NULL
188	               AND NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote_id) THEN
189	                v_lote_id := NULL;
190	            END IF;
191	
192	            v_motivo := CASE WHEN p_tipo = 'entrada' THEN 'scanner_lote' ELSE 'saida_inteira' END;
193	            v_observacoes := (CASE WHEN p_tipo = 'entrada' THEN 'Entrada' ELSE 'Saída inteira' END)
194	                || ' via Scanner QR — ' || COALESCE(v_tipo_embalagem, 'container')
195	                || ' de ' || v_qty::text || ' ' || COALESCE(v_embalagem_nome, 'un')
196	                || ' · Lote ' || COALESCE(v_lote, '—');
197	
198	            INSERT INTO movimentacoes (
